package android.view;import java.util.*;public class View {public void clearFocus(){}public Object getWindowToken(){return null;}public float alpha=1;public float getAlpha(){return alpha;}public void setAlpha(float a){alpha=a;}static int next=1;int id;Object tag;public boolean enabled=true;public OnClickListener click;public List<View> children=new ArrayList<>();public interface OnClickListener{void onClick(View v);}public static int generateViewId(){return next++;}public void setId(int i){id=i;}public int getId(){return id;}public void setTag(Object o){tag=o;}public Object getTag(){return tag;}public void setEnabled(boolean b){enabled=b;}public void setOnClickListener(OnClickListener l){click=l;}public void performClick(){if(enabled&&click!=null)click.onClick(this);}public void setPadding(int a,int b,int c,int d){}public void setBackground(Object o){}public void setContentDescription(String s){}public View findViewById(int i){if(id==i)return this;for(View v:children){View f=v.findViewById(i);if(f!=null)return f;}return null;}}
